changeSet.sql:
CREATE TABLE IF NOT EXISTS watchlist_channel (
    watchlist_id INTEGER NOT NULL,
    channel_id   INTEGER NOT NULL,
    PRIMARY KEY (watchlist_id, channel_id),
    FOREIGN KEY (watchlist_id) REFERENCES watchlist(id) ON DELETE CASCADE,
    FOREIGN KEY (channel_id) REFERENCES channel(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_watchlist_channel_channel_id ON watchlist_channel (channel_id);

COMMENT ON TABLE watchlist_channel IS 'Junction table linking watchlists to channels for efficient reverse lookups';
COMMENT ON COLUMN watchlist_channel.watchlist_id IS 'Reference to the watchlist';
COMMENT ON COLUMN watchlist_channel.channel_id IS 'Reference to the channel';
COMMENT ON INDEX idx_watchlist_channel_channel_id IS 'Index for reverse lookups: find all watchlists containing a channel';
